    [Test]
    public void GenerateDumbConsensus_BiopythonDocExamples()
    {
        // Biopython 1.85 dumb_consensus deprecation-warning doctest (ANGT); the gap_consensus doctest rows give NTGT here (gaps are not emitted).
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "ACGT", "ATGT", "ATGT" }, ambiguous: 'N'), Is.EqualTo("ANGT"));
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "ACGT", "AT-T", "CT-T", "GT-T" }, ambiguous: 'N'), Is.EqualTo("NTGT"));
    }

    [Test]
    public void GenerateDumbConsensus_EdgeCases()
    {
        Assert.That(MotifFinder.GenerateDumbConsensus(Array.Empty<string>()), Is.EqualTo(""));
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "--", ".." }), Is.EqualTo("XX"), "all-gap column");
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "A", "-" }), Is.EqualTo("A"));
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "A", "-" }, requireMultiple: true), Is.EqualTo("X"));
        Assert.That(MotifFinder.GenerateDumbConsensus(new[] { "A", "a" }, threshold: 0), Is.EqualTo("X"), "case-sensitive tie");
        Assert.Throws<ArgumentNullException>(() => MotifFinder.GenerateDumbConsensus(null!));
        Assert.Throws<ArgumentException>(() => MotifFinder.GenerateDumbConsensus(new[] { "AC", "A" }));
        Assert.Throws<ArgumentOutOfRangeException>(() => MotifFinder.GenerateDumbConsensus(new[] { "A" }, double.NaN));
    }

