    [Test]
    public void GenerateConsensus_DefaultThreshold_IdenticalToParameterlessOverload()
    {
        var rows = new[] { "ACGTTA", "ACGAAT", "TCGACA", "GCC-NA", "ACTTGA" };
        Assert.That(MotifFinder.GenerateConsensus(rows, 0.25), Is.EqualTo(MotifFinder.GenerateConsensus(rows)));
    }

    [Test]
    public void GenerateConsensus_Threshold_HandDerived()
    {
        // Column A,A,A,C,G (n = 5): threshold 0 -> {A,C,G} = V; 0.25 (> 1.25) -> A; 0.6 (> 3) -> none pass -> max A.
        var rows = new[] { "A", "A", "A", "C", "G" };
        Assert.That(MotifFinder.GenerateConsensus(rows, 0.0), Is.EqualTo("V"));
        Assert.That(MotifFinder.GenerateConsensus(rows, 0.1), Is.EqualTo("V"));
        Assert.That(MotifFinder.GenerateConsensus(rows, 0.2), Is.EqualTo("A"));
        Assert.That(MotifFinder.GenerateConsensus(rows, 0.6), Is.EqualTo("A"));
        Assert.That(MotifFinder.GenerateConsensus(new[] { "A", "C" }, 1.0), Is.EqualTo("M"), "tie fallback");
    }

    [Test]
    public void GenerateConsensus_Threshold_Guards()
    {
        Assert.Throws<ArgumentNullException>(() => MotifFinder.GenerateConsensus(null!, 0.25));
        Assert.Throws<ArgumentOutOfRangeException>(() => MotifFinder.GenerateConsensus(new[] { "A" }, -0.01));
        Assert.Throws<ArgumentOutOfRangeException>(() => MotifFinder.GenerateConsensus(new[] { "A" }, 1.01));
        Assert.Throws<ArgumentOutOfRangeException>(() => MotifFinder.GenerateConsensus(new[] { "A" }, double.NaN));
        Assert.Throws<ArgumentException>(() => MotifFinder.GenerateConsensus(new[] { "A", "AC" }, 0.25));
    }

